//! Generates code into OUT_DIR, which the crate includes.

use std::{env, fs, path::Path};

fn main() {
    let out = env::var_os("OUT_DIR").expect("cargo sets OUT_DIR");
    fs::write(
        Path::new(&out).join("generated.rs"),
        "/// Generated by build.rs.\npub fn generated() -> u8 { 1 }\n",
    )
    .expect("OUT_DIR is writable");
    println!("cargo:rerun-if-changed=build.rs");
}
